SELECT COUNT(*) FROM votes as v, comments as c, posts as p WHERE p.Id = v.PostId AND p.Id = c.PostId AND v.VoteTypeId=2 AND v.CreationDate<='2014-09-11 00:00:00'::timestamp AND c.CreationDate>='2010-08-06 12:21:39'::timestamp AND c.CreationDate<='2014-09-11 20:55:34'::timestamp AND p.Score>=0 AND p.Score<=13 AND p.FavoriteCount>=0;